        <section class="cart-shell"><div class="wrap"><div class="account-head"><div><div class="eyebrow">Order details</div><h1 style="margin:6px 0">{{ $order->order_number }}</h1><div class="muted">Placed {{ $order->created_at?->format('M j, Y g:i A') }}</div></div><span class="status-pill">{{ str_replace('_',' ', $order->status) }}</span></div><div class="detail-grid"><div class="checkout-card"><h2>Items</h2>@foreach($order->items as $item)<div class="summary-row"><span>{{ $item->title }} @if($item->option_label)<small class="muted">({{ $item->option_label }})</small>@endif × {{ $item->quantity }}</span><strong>{{ $money($item->line_total_minor) }}</strong></div>@endforeach<div class="summary-row"><span>Subtotal</span><strong>{{ $money($order->subtotal_minor) }}</strong></div>@if(($order->discount_minor ?? 0) > 0)<div class="summary-row"><span>Discount @if($order->coupon_code)<small class="muted">({{ $order->coupon_code }})</small>@endif</span><strong>-{{ $money($order->discount_minor) }}</strong></div>@endif<div class="summary-row"><span>Shipping</span><strong>{{ $order->shipping_minor === 0 ? 'Free' : $money($order->shipping_minor) }}</strong></div><div class="summary-row"><span>Tax</span><strong>{{ $money($order->tax_minor) }}</strong></div><div class="summary-row summary-total"><span>Total</span><strong>{{ $money($order->total_minor) }}</strong></div>@if($order->refunds->count())<h2 style="margin-top:28px">Refunds</h2>@foreach($order->refunds as $refund)<div class="summary-row"><span>{{ $refund->reason ?: 'Refund' }}</span><strong>-{{ $money($refund->amount_minor) }}</strong></div>@endforeach @endif</div><aside class="summary-card"><h2>Fulfillment</h2><div class="summary-row"><span>Payment</span><strong style="text-transform:capitalize">{{ str_replace('_',' ', $order->payment_status) }}</strong></div><div class="summary-row"><span>Order</span><strong style="text-transform:capitalize">{{ str_replace('_',' ', $order->status) }}</strong></div>@if($order->shipping_method)<div class="summary-row"><span>Shipping</span><strong>{{ $order->shipping_method }}</strong></div>@endif
